<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Acceso | Salud Vida</title><link rel="stylesheet" href="assets/app.css"></head><body class="login-page"><div class="login-card"><div class="brand"><img class="brand-logo" src="assets/salud-vida-logo.png" alt="Logo Salud Vida"><span><b>Salud Vida</b><small>Gestión clínica integral</small></span></div><h1>Ingresa a tu clínica.</h1><p class="muted">Usa el administrador creado en <code>sql/crear_admin.sql</code>.</p><?php if($flash): ?><div class="alert <?=e($flash[0])?>"><?=e($flash[1])?></div><?php endif; ?><form method="post" class="form" id="loginForm"><input type="hidden" name="action" value="login"><input type="hidden" name="login_mode" id="loginMode" value="password"><input type="hidden" name="login_descriptor" id="loginDescriptor"><div class="login-methods"><button type="button" class="btn outline login-tab active" data-mode="password">Entrar con contraseña</button><button type="button" class="btn outline login-tab" data-mode="face">Entrar con rostro</button></div><div id="passwordLogin"><label>Usuario<input name="username" value="admin" required></label><label>Contraseña<input name="password" type="password" value="admin123" required></label><button class="btn primary" type="submit">Ingresar al sistema</button></div><div id="faceLogin" hidden><video id="loginVideo" autoplay muted playsinline></video><p id="loginStatus" class="face-status">Pulsa iniciar cámara para buscar tu rostro.</p><button type="button" class="btn outline" id="startLoginCamera">Iniciar cámara</button><button type="button" class="btn primary" id="scanLoginFace" disabled>Escanear rostro</button><button class="btn primary" id="loginByFace" type="submit" hidden>Confirmar acceso facial</button></div></form></div><script src="https://cdn.jsdelivr.net/npm/@vladmandic/face-api@1.7.15/dist/face-api.js"></script><script>document.addEventListener('DOMContentLoaded',()=>{const f=document.getElementById('loginForm');if(!f)return;const tabs=[...document.querySelectorAll('.login-tab')],pass=document.getElementById('passwordLogin'),face=document.getElementById('faceLogin'),mode=document.getElementById('loginMode'),desc=document.getElementById('loginDescriptor'),video=document.getElementById('loginVideo'),status=document.getElementById('loginStatus'),start=document.getElementById('startLoginCamera'),scan=document.getElementById('scanLoginFace'),confirm=document.getElementById('loginByFace');let ready=false,stream,valid=false;tabs.forEach(t=>t.onclick=()=>{mode.value=t.dataset.mode;tabs.forEach(x=>x.classList.toggle('active',x===t));pass.hidden=t.dataset.mode==='face';face.hidden=t.dataset.mode!=='face';f.querySelector('[name=username]').required=t.dataset.mode==='password';f.querySelector('[name=password]').required=t.dataset.mode==='password';});async function load(){if(ready)return true;status.textContent='Cargando detector facial…';try{const u='https://justadudewhohacks.github.io/face-api.js/models';await faceapi.nets.tinyFaceDetector.loadFromUri(u);await faceapi.nets.faceLandmark68Net.loadFromUri(u);await faceapi.nets.faceRecognitionNet.loadFromUri(u);ready=true;return true;}catch(e){status.textContent='No se pudo cargar el detector facial.';return false;}}start.onclick=async()=>{if(!await load())return;try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});video.srcObject=stream;scan.disabled=false;start.disabled=true;status.textContent='Cámara activa. Centra tu rostro y pulsa escanear.';}catch(e){status.textContent='Autoriza la cámara y usa localhost o HTTPS.';}};scan.onclick=async()=>{status.textContent='Analizando rostro…';const r=await faceapi.detectSingleFace(video,new faceapi.TinyFaceDetectorOptions({inputSize:320,scoreThreshold:.6})).withFaceLandmarks().withFaceDescriptor();if(!r){valid=false;status.textContent='No se detectó ningún rostro.';return;}desc.value=JSON.stringify(Array.from(r.descriptor));valid=true;confirm.hidden=false;scan.disabled=true;status.textContent='Rostro detectado. Confirma para buscar coincidencia.';};f.onsubmit=e=>{if(mode.value==='face'&&!valid){e.preventDefault();status.textContent='Primero escanea un rostro válido.';}};});</script><script>document.addEventListener("click",e=>{const i=e.target.closest(".med-photo");if(!i)return;const m=document.createElement("div");m.className="photo-modal";m.innerHTML='<button aria-label="Cerrar">×</button><img src="'+i.src+'" alt="Foto ampliada">';m.onclick=x=>{if(x.target===m||x.target.tagName==="BUTTON")m.remove()};document.body.appendChild(m)});</script></body></html><?php exit; endif;

