id_persona=c.id_medico JOIN personas p ON p.id_persona=m.id_persona WHERE p.nombre LIKE ? OR p.ci LIKE ? ORDER BY c.activo DESC,c.fecha_inicio DESC',['%'.$personalSearch.'%','%'.$personalSearch.'%']); $consultas=rows($pdo,'SELECT c.*,p.nombre paciente,d.nombre medico,e.nombre especialidad,co.numero consultorio FROM consultas c JOIN personas p ON p.id_persona=c.id_persona JOIN personas d ON d.id_persona=c.id_medico JOIN especialidades e ON e.id_especialidad=c.id_especialidad JOIN consultorios co ON co.id_consultorio=c.id_consultorio ORDER BY c.fecha_hora DESC'); $surgeries=rows($pdo,'SELECT c.*,p.nombre paciente,e.nombre especialidad,q.nombre quirofano,d.nombre cirujano FROM cirugias c JOIN personas p ON p.id_persona=c.id_persona JOIN especialidades e ON e.id_especialidad=c.id_especialidad JOIN quirofanos q ON q.id_quirofano=c.id_quirofano JOIN personas d ON d.id_persona=c.id_cirujano_principal ORDER BY c.fecha_programada DESC'); $interns=rows($pdo,'SELECT i.*,p.nombre paciente,h.numero habitacion FROM internaciones i JOIN personas p ON p.id_persona=i.id_persona JOIN habitaciones h ON h.id_habitacion=i.id_habitacion ORDER BY i.fecha_ingreso DESC'); $ins=rows($pdo,'SELECT i.id_internacion,i.id_persona,p.nombre paciente FROM internaciones i JOIN personas p ON p.id_persona=i.id_persona WHERE i.estado="ACTIVA"'); $insurance=rows($pdo,'SELECT ps.id_paciente_seguro,ps.id_persona,p.nombre,a.nombre aseguradora,ps.numero_poliza FROM paciente_seguro ps JOIN personas p ON p.id_persona=ps.id_persona JOIN aseguradoras a ON a.id_aseguradora=ps.id_aseguradora WHERE ps.activo=1 ORDER BY p.nombre'); $invoices=rows($pdo,'SELECT f.*,p.nombre paciente,d.razon_social FROM facturas f JOIN paciente_seguro ps ON ps.id_paciente_seguro=f.id_paciente_seguro JOIN personas p ON p.id_persona=ps.id_persona JOIN datos_facturacion d ON d.id_datos_facturacion=f.id_datos_facturacion ORDER BY f.fecha_emision DESC'); $users=[]; if($page==='usuarios'&&can(['ADMINISTRADOR']))$users=rows($pdo,'SELECT u.id_