function select_options(array $items,string $value,string $label,mixed $selectedValue=null): void { foreach($items as $i) { $text=(string)$i[$label]; if(isset($i['ci'])) $text.=' · CI '.(string)$i['ci']; if(isset($i['matricula_profesional'])) $text.=' · Mat. '.(string)$i['matricula_profesional']; echo '<option value="'.e((string)$i[$value]).'"'.selected($i[$value],$selectedValue).'>'.e($text).'</option>'; } }
function page_form(string $id,string $action,string $button,string $content): void { global $types,$specialties; ob_start(); select_options($types ?? [],'id_tipo_habitacion','nombre'); $typeOptions=ob_get_clean(); ob_start(); select_options($specialties ?? [],'id_especialidad','nombre'); $specialtyOptions=ob_get_clean(); $content=str_replace('<?php select_options($types,"id_tipo_habitacion","nombre");?>',$typeOptions,$content); $content=str_replace('<?php select_options($specialties,"id_especialidad","nombre");?>',$specialtyOptions,$content); echo '<form id="'.e($id).'" class="card form-grid" method="post" enctype="multipart/form-data"><input type="hidden" name="action" value="'.e($action).'">'.$content.'<button class="btn primary" type="submit">'.e($button).'</button></form>'; }
