<?php elseif($page==='servicios'): ?><?php $serviceRows=rows($pdo,'SELECT s.id_servicio,s.nombre,s.id_especialidad,s.activo,e.nombre especialidad,COALESCE((SELECT ph.precio FROM servicio_precio_historico ph WHERE ph.id_servicio=s.id_servicio AND ph.fecha_desde<=CURDATE() ORDER BY ph.fecha_desde DESC LIMIT 1),0) precio_actual FROM servicios_medicos s LEFT JOIN especialidades e ON e.id_especialidad=s.id_especialidad ORDER BY s.nombre'); $priceRows=rows($pdo,'SELECT ph.id_precio,ph.id_servicio,ph.precio,ph.fecha_desde,s.nombre servicio FROM servicio_precio_historico ph JOIN servicios_medicos s ON s.id_servicio=ph.id_servicio ORDER BY ph.fecha_desde DESC,s.nombre'); ?><div class="page-intro"><div><span class="eyebrow">CATÁLOGO DE ATENCIÓN</span><h2>Servicios médicos y tarifas</h2><p class="muted">Una nueva tarifa se aplica desde su fecha de inicio. Los precios anteriores permanecen en el historial.</p></div><a class="btn outline" href="?action=export_excel&export_page=servicios">Exportar servicios</a></div><?php if(can(['ADMINISTRADOR','SUPERVISOR'])): ?><form class="card form-grid" method="post"><input type="hidden" name="action" value="crear_servicio"><label>Nombre del servicio<input name="nombre" required></label><label>Especialidad<select name="id_especialidad"><option value="0">Sin asignar</option><?php select_options($specialties,'id_especialidad','nombre');?></select></label><label>Precio inicial<input name="precio" type="number" min="0" step="0.01" required></label><button class="btn primary" type="submit">Crear servicio</button></form><form class="card form-grid" method="post"><input type="hidden" name="action" value="add_service_price"><label>Servicio<select name="id_servicio" required><?php foreach($serviceRows as $s):?><option value="<?=$s['id_servicio']?>"><?=e($s['nombre'])?></option><?php endforeach;?></select></label><label>Nuevo precio<input name="precio" type="number" min="0" step="0.01" required></label><label>Vigente desde<input name="fecha_desde" type="date" value="<?=date('Y-m-d')?>" required></label><button class="btn primary" type="submit">Registrar nueva tarifa</button></form><?php endif; ?><div class="card table-wrap"><h3>Servicios actuales</h3><table><thead><tr><th>Servicio</th><th>Especialidad</th><th>Precio vigente</th><th>Estado</th><th>Modificar</th></tr></thead><tbody><?php foreach($serviceRows as $s):?><tr><td><?=e($s['nombre'])?></td><td><?=e($s['especialidad']?:'General')?></td><td><?=e(number_format((float)$s['precio_actual'],2,'.',''))?></td><td><?= $s['activo']?'Activo':'Inactivo'?></td><td><?php if(can(['ADMINISTRADOR','SUPERVISOR'])):?><form class="inline" method="post"><input type="hidden" name="action" value="update_service"><input type="hidden" name="id_servicio" value="<?=$s['id_servicio']?>"><input name="nombre" value="<?=e($s['nombre'])?>" required><select name="id_especialidad" class="compact-select"><option value="0">General</option><?php select_options($specialties,'id_especialidad','nombre',$s['id_especialidad']);?></select><button class="link">Guardar</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><div class="card table-wrap"><h3>Historial de tarifas</h3><table><thead><tr><th>Servicio</th><th>Precio</th><th>Vigente desde</th></tr></thead><tbody><?php foreach($priceRows as $pr):?><tr><td><?=e($pr['servicio'])?></td><td><?=e(number_format((float)$pr['precio'],2,'.',''))?></td><td><?=e($pr['fecha_desde'])?></td></tr><?php endforeach;?></tbody></table></div>
