<?php elseif($page==='internaciones'): ?><div class="page-intro"><div><span class="eyebrow">HOSPITALIZACIÓN</span><h2>Internaciones</h2><p class="muted">Crea órdenes de internación, asigna habitaciones y registra altas médicas.</p></div><a class="btn outline" href="?action=export_excel&export_page=internaciones">Exportar internaciones</a></div><?php ob_start();?><label>Consulta de origen<select name="id_consulta" required><?php foreach($consultas as $c):?><option value="<?=$c['id_consulta']?>"><?=e($c['fecha_hora'].' · '.$c['paciente'])?></option><?php endforeach;?></select></label><label>Paciente<select name="id_persona" required><?php select_options($patients,'id_persona','nombre');?></select></label><label>Habitación disponible<select name="id_habitacion" required><?php foreach($rooms as $r):?><option value="<?=$r['id_habitacion']?>"><?=e($r['numero'].' · '.$r['tipo'])?></option><?php endforeach;?></select></label><label>Ingreso<input type="datetime-local" name="fecha_ingreso" required></label><label>Motivo<textarea name="motivo" required></textarea></label><?php $c=ob_get_clean(); if(!in_array('internaciones',$missingTables,true)) page_form('inpatientForm','crear_internacion','Crear internación',$c); else { echo '<div class="card empty"><h3>Internaciones no disponibles</h3><p>Tu SQL actual no contiene la tabla <code>internaciones</code>. Importa un esquema que la incluya para activar este módulo.</p></div>'; } ?><div class="card table-wrap"><table><thead><tr><th>Paciente</th><th>Habitación</th><th>Ingreso</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach($interns as $i):?><tr><td><?=e($i['paciente'])?></td><td><?=e($i['habitacion'])?></td><td><?=e($i['fecha_ingreso'])?></td><td><?=e($i['estado'])?></td><td><?php if($i['estado']==='ACTIVA'):?><form class="inline" method="post"><input type="hidden" name="action" value="alta_internacion"><input type="hidden" name="id_internacion" value="<?=$i['id_internacion']?>"><button class="link">Registrar alta</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
<?php elseif($page==='facturacion'): ?><div class="page-intro"><div><span class="eyebrow">ADMINISTRACIÓN</span><h2>Facturación</h2><p class="muted">Emite facturas con detalle vinculado a una consulta, cirugía o internación.</p></div><a class="btn outline" href="?action=export_excel&export_page=facturacion">Exportar facturación</a></div><?php ob_start();?><label>Póliza/paciente<select name="id_paciente_seguro" required><?php foreach($insurance as $i):?><option value="<?=$i['id_paciente_seguro']?>"><?=e($i['paciente'].' · '.$i['aseguradora'].' · '.$i['numero_poliza'])?></option><?php endforeach;?></select></label><label>Servicio<select name="id_servicio" required onchange="document.getElementById('price').value=this.options[this.selectedIndex].dataset.price"><?php foreach($services as $s):?><option data-price="<?=$s['precio']?>" value="<?=$s['id_servicio']?>"><?=e($s['nombre'].' · '.$s['precio'])?></option><?php endforeach;?></select></label><label>Origen<select name="origen" id="invoiceOrigin" onchange="toggleInvoiceOrigin()"><option value="consulta">Consulta</option><option value="cirugia">Cirugía</option><option value="internacion">Internación</option></select></label><label id="originConsulta">Consulta realizada<select name="id_origen"><option value="">Selecciona una consulta</option><?php foreach($consultas as $c):?><option value="<?=$c['id_consulta']?>"><?=e($c['id_consulta'].' · '.$c['fecha_hora'].' · '.$c['paciente'])?></option><?php endforeach;?></select></label><label id="originCirugia" hidden>Cirugía realizada<select name="id_origen" disabled><option value="">Selecciona una cirugía</option><?php foreach($surgeries as $s):?><option value="<?=$s['id_cirugia']?>"><?=e($s['id_cirugia'].' · '.$s['fecha_programada'].' · '.$s['paciente'])?></option><?php endforeach;?></select></label><label id="originInternacion" hidden>Internación registrada<select name="id_origen" disabled><option value="">Selecciona una internación</option><?php foreach($interns as $i):?><option value="<?=$i['id_internacion']?>"><?=e($i['id_internacion'].' · '.$i['fecha_ingreso'].' · '.$i['paciente'])?></option><?php endforeach;?></select></label><label>Cantidad<input type="number" name="cantidad" min="1" value="1" required></label><label>Precio unitario<input id="price" type="number" step="0.01" name="precio_unitario" min="0" value="0" required></label><label>Cobertura del seguro<input type="number" step="0.01" name="cobertura" min="0" value="0"></label><label>Tipo de pago<select name="tipo_pago"><option>PARTICULAR</option><option>SEGURO</option><option>MIXTO</option></select></label><label>NIT/CI<input name="nit_ci" required></label><label>Razón social<input name="razon_social" required></label><label>Documento fiscal<select name="tipo_documento_fiscal"><option>FACTURA_CREDITO_FISCAL</option><option>FACTURA_SIN_CREDITO_FISCAL</option><option>RECIBO</option></select></label><?php $c=ob_get_clean(); if(can(['ADMINISTRADOR','FACTURADOR']) && !in_array('facturas',$missingTables,true)) page_form('invoiceForm','crear_factura','Emitir factura',$c); elseif(in_array('facturas',$missingTables,true)) { echo '<div class="card empty"><h3>Facturación no disponible</h3><p>Tu SQL actual no contiene las tablas necesarias para facturación, como <code>facturas</code> y <code>servicios_medicos</code>.</p></div>'; } ?><div class="card table-wrap"><table><thead><tr><th>N.º</th><th>Paciente</th><th>Fecha</th><th>Subtotal</th><th>Total</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach($invoices as $f):?><tr><td><?=e($f['id_factura'])?></td><td><?=e($f['paciente'])?></td><td><?=e($f['fecha_emision'])?></td><td><?=e($f['subtotal'])?></td><td><?=e($f['total'])?></td><td><?=e($f['estado'])?></td><td><form class="inline" method="post"><input type="hidden" name="action" value="estado_factura"><input type="hidden" name="id_factura" value="<?=$f['id_factura']?>"><select name="estado"><option>PENDIENTE</option><option>PAGADA</option><option>ANULADA</option></select><button class="link">Actualizar</button></form></td></tr><?php endforeach;?></tbody></table></div>
<?php elseif($page==='reportes'): ?><div class="page-intro"><div><span class="eyebrow">ANÁLISIS</span><h2>Reportes</h2><p class="muted">Resumen diario de facturación agrupado por estado.</p></div></div><div class="card table-wrap"><table><thead><tr><th>Fecha</th><th>Estado</th><th>Cantidad</th><th>Total</th></tr></thead><tbody><?php foreach($report as $r):?><tr><td><?=e($r['fecha'])?></td><td><?=e($r['estado'])?></td><td><?=e($r['cantidad'])?></td><td><?=e($r['total'])?></td></tr><?php endforeach;?></tbody></table></div>
<?php elseif($page==='bitacora'): ?><div class="page-intro"><div><span class="eyebrow">AUDITORÍA</span><h2>Bitácora</h2><p class="muted">Historial de operaciones y cambios registrados por la base de datos.</p></div><a class="btn outline" href="?action=export_excel&export_page=bitacora">Exportar bitácora</a></div><div class="card table-wrap"><table><thead><tr><th>Fecha</th><th>Tabla</th><th>ID</th><th>Acción</th><th>Detalle</th></tr></thead><tbody><?php foreach($logs as $l):?><tr><td><?=e($l['fecha_hora'])?></td><td><?=e($l['tabla_afectada'])?></td><td><?=e($l['id_registro'])?></td><td><?=e($l['accion'])?></td><td><?=e((string)($l['detalle']??'Sin detalle'))?></td></tr><?php endforeach;?></tbody></table></div>
<?php elseif($page==='usuarios'&&can(['ADMINISTRADOR'])): ?><div class="page-intro"><div><span class="eyebrow">CONTROL DE ACCESO</span><h2>Usuarios y roles</h2></div><div class="page-actions"><a class="btn outline" href="?action=export_excel&export_page=usuarios">Exportar usuarios</a><a class="btn outline" href="?page=seguridad">Registro facial</a></div></div><?php page_form('userForm','crear_usuario','Guardar usuario','<label>CI<input name="ci" required></label><label>Nombre completo<input name="nombre" required></label><label>Fecha de nacimiento<input name="fecha_nacimiento" type="date" required></label><label>Usuario<input name="username" required></label><label>Contraseña<input name="password" type="password" required></label><label>Rol<select name="rol"><option>ADMINISTRADOR</option><option>MEDICO</option><option>ENFERMERO</option><option>FACTURADOR</option><option>SUPERVISOR</option></select></label><label>Teléfono<input name="telefono"></label><label>Correo<input name="correo" type="email"></label><label>Tipo de persona<select name="tipo_persona"><option value="PERSONAL_HOSPITAL">Personal del hospital</option><option value="USUARIO_EXTERNO">Usuario externo</option></select></label>');?><div class="card table-wrap"><table><thead><tr><th>Persona</th><th>Usuario</th><th>Rol</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['nombre'])?></td><td><?=e($u['nombre_usuario'])?></td><td><?=e($u['rol'])?></td><td><?= $u['estado']?'Habilitado':'Deshabilitado'?></td><td><form class="inline" method="post"><input type="hidden" name="action" value="change_role"><input type="hidden" name="id_usuario" value="<?=$u['id_usuario']?>"><select name="rol" class="compact-select"><option <?= $u['rol']==='ADMINISTRADOR'?'selected':''?>>ADMINISTRADOR</option><option <?= $u['rol']==='SUPERVISOR'?'selected':''?>>SUPERVISOR</option><option <?= $u['rol']==='MEDICO'?'selected':''?>>MEDICO</option><option <?= $u['rol']==='ENFERMERO'?'selected':''?>>ENFERMERO</option><option <?= $u['rol']==='FACTURADOR'?'selected':''?>>FACTURADOR</option><option <?= $u['rol']==='PACIENTE'?'selected':''?>>PACIENTE</option></select><button class="link">Cambiar rol</button></form><form class="inline" method="post"><input type="hidden" name="action" value="toggle_user"><input type="hidden" name="id_usuario" value="<?=$u['id_usuario']?>"><button class="link">Cambiar estado</button></form><a class="link" href="?page=seguridad&persona=<?=$u['id_persona']?>" title="Editar registro facial">◉ Rostro</a><form class="inline" method="post" onsubmit="return confirm('¿Eliminar esta cuenta?')"><input type="hidden" name="action" value="delete_user"><input type="hidden" name="id_usuario" value="<?=$u['id_usuario']?>"><button class="danger">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div>
<?php endif;?></section></main></div><script>function toggleInvoiceOrigin(){const v=document.getElementById('invoiceOrigin').value;['consulta','cirugia','internacion'].forEach(k=>{const box=document.getElementById('origin'+k.charAt(0).toUpperCase()+k.slice(1));const sel=box.querySelector('select');const active=k===v;box.hidden=!active;sel.disabled=!active;sel.required=active;});}document.addEventListener('DOMContentLoaded',()=>{if(document.getElementById('invoiceOrigin'))toggleInvoiceOrigin();});</script><script src="https://cdn.jsdelivr.net/npm/@vladmandic/face-api@1.7.15/dist/face-api.js"></script><script>document.addEventListener('DOMContentLoaded',()=>{const f=document.getElementById('faceForm');if(!f)return;const tabs=[...document.querySelectorAll('.face-tab')],photo=document.getElementById('photoMode'),cam=document.getElementById('cameraMode'),mode=document.getElementById('modoRegistro'),file=document.getElementById('rostroFile'),desc=document.getElementById('faceDescriptor'),video=document.getElementById('faceVideo'),status=document.getElementById('faceStatus'),guide=document.getElementById('faceGuide'),start=document.getElementById('startCamera'),capture=document.getElementById('captureFace'),save=document.getElementById('saveFace');let stream,ready=false,valid=false;function setMode(m){mode.value=m;tabs.forEach(t=>t.classList.toggle('active',t.dataset.mode===m));photo.hidden=m!=='foto';cam.hidden=m!=='tiempo_real';file.required=m==='foto';save.hidden=m==='tiempo_real';if(m==='foto'){valid=false;desc.value='';status.textContent='Selecciona una fotografía clara y frontal.';}}tabs.forEach(t=>t.addEventListener('click',()=>setMode(t.dataset.mode)));async function models(){if(ready)return true;status.textContent='Cargando detector facial…';try{const u='https://justadudewhohacks.github.io/face-api.js/models';await faceapi.nets.tinyFaceDetector.loadFromUri(u);await faceapi.nets.faceLandmark68Net.loadFromUri(u);await faceapi.nets.faceRecognitionNet.loadFromUri(u);ready=true;return true;}catch(e){status.textContent='No se pudo cargar el detector facial. Revisa la conexión e inténtalo nuevamente.';return false;}}start.addEventListener('click',async()=>{if(!await models())return;try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:480}},audio:false});video.srcObject=stream;start.disabled=true;capture.disabled=false;guide.textContent='Buscando un solo rostro…';status.textContent='Cámara activa. Centra tu rostro y mira de frente.';}catch(e){status.textContent='No se pudo acceder a la cámara. Autoriza el permiso del navegador.';}});capture.addEventListener('click',async()=>{status.textContent='Analizando rostro…';const r=await faceapi.detectSingleFace(video,new faceapi.TinyFaceDetectorOptions({inputSize:320,scoreThreshold:.6})).withFaceLandmarks().withFaceDescriptor();if(!r){valid=false;status.textContent='No se detectó ningún rostro. Acércate, mejora la luz y mira de frente.';guide.textContent='Rostro no detectado';return;}if(r.detection.score<.75){valid=false;status.textContent='La detección es débil. Mantén el rostro centrado.';return;}desc.value=JSON.stringify(Array.from(r.descriptor));valid=true;capture.disabled=true;capture.textContent='Rostro detectado';guide.textContent='Rostro detectado correctamente';status.textContent='Registro válido. Confirma para guardar y reemplazar la fotografía anterior.';save.hidden=false;save.textContent='Confirmar registro facial';});f.addEventListener('submit',e=>{if(mode.value==='tiempo_real'&&!valid){e.preventDefault();status.textContent='Primero pulsa “Registrar rostro” y espera la confirmación.';}});});</script><script>document.addEventListener("click",e=>{const i=e.target.closest(".med-photo");if(!i)return;const m=document.createElement("div");m.className="photo-modal";m.innerHTML='<button aria-label="Cerrar">×</button><img src="'+i.src+'" alt="Foto ampliada">';m.onclick=x=>{if(x.target===m||x.target.tagName==="BUTTON")m.remove()};document.body.appendChild(m)});</script></body></html>
